arguments.code:
const paths = ["package.json", "release/local-signoff.json", "website/package.json"];
const results = await Promise.all(paths.map(async path => {
  try {
    const r = await tools.read_file({path});
    return {path, content: typeof r === "string" ? r : (r.content ?? JSON.stringify(r)), absent: false};
  } catch (e) {
    return {path, absent: true};
  }
}));
return results;

